# compact aliases for code fences / question sections.
def block_section(qid, p):
    metrics = '\n'.join(f'- `{m}`' if '`' not in m else f'- {m}' for m in p['metrics'])
    follows = '\n'.join(f'{i+1}. {x}' for i,x in enumerate(p['follow']))
    return f'''\n{MARK}\n## 专业增强版 V2：机制、量化与验证\n\n> 本节是在 PDF 基线题解之上的**仓库扩展**。目标是把“能背答案”升级为“能解释硬件因果、能量化、能用 profiler 证伪”。\n\n### 1. 硬件机制与核心心智模型\n\n{p['model']}\n\n### 2. 定量推导 / 性能模型\n\n{p['quantitative']}\n\n面试时不要只报公式。至少说明：公式里的变量对应什么硬件资源、哪些是假设、实际值应该如何由 profiler 或 microbenchmark 得到。\n\n### 3. 代码 / 白板核心片段\n\n```cpp\n{p['code']}\n```\n\n白板代码优先保证：**边界正确、同步范围正确、地址模式可解释**。如果为了展示优化而省略边界处理，要主动说明省略条件。\n\n### 4. Nsight 证据链：怎样证明你的判断\n\n{metrics}\n\n推荐把分析写成四列：\n\n| 假设 | 预期指标变化 | 实测指标变化 | 结论 |\n|---|---|---|---|\n| 当前瓶颈是本题讨论的问题 | 指标应出现可预测变化 | benchmark 后填写 | 接受 / 推翻假设 |\n| 优化应减少对应硬件成本 | 时间与因果指标同向改善 | benchmark 后填写 | 是否保留优化 |\n\n### 5. 架构迁移视角\n\n{p['arch']}\n\n这里要区分两类知识：\n\n- **稳定原理**：warp 粒度、数据复用、依赖、Roofline、资源平衡等；\n- **架构实现**：具体指令、cache/SM 资源、TMA/TMEM/cluster/TCGen05 等。\n\n面试中如果不确定某代 GPU 的精确容量或吞吐，不要猜数字；说明“会查目标 compute capability / tuning guide 并重新 profile”比报错数字更专业。\n\n### 6. 可复现实验（建议真的做）\n\n{p['experiment']}\n\n实验至少记录：GPU 型号、compute capability、CUDA/driver、编译参数、输入 shape/dtype、warm-up、迭代次数、median/p95、correctness tolerance，以及关键 Nsight 指标。\n\n### 7. 深挖追问树\n\n{follows}\n\n### 8. 高分回答检查清单\n\n- [ ] 先用一句话给出正确结论，而不是先铺背景。\n- [ ] 能画出本题涉及的 warp / memory / pipeline 数据流。\n- [ ] 能给至少一个公式、数量级或资源约束。\n- [ ] 能指出一个“看似优化、实际可能变慢”的反例。\n- [ ] 能说出用哪些 Nsight 证据验证。\n- [ ] 能区分稳定原理与 Ampere/Hopper/Blackwell 的架构细节。\n- [ ] 工程场景下会先与 CUDA Library / CUB / cuBLAS / CUTLASS 等成熟基线比较（适用时）。\n'''

# qid->path
paths={}
for f in QROOT.rglob('q[0-9][0-9][0-9].md'):
    m=re.fullmatch(r'q(\d{3})\.md', f.name)
    if m: paths[int(m.group(1))]=f

missing=set(range(1,101))-set(P)
if missing:
    raise SystemExit(f'Missing profiles: {sorted(missing)}')
if set(paths)!=set(range(1,101)):
    raise SystemExit(f'Question files mismatch: {sorted(set(range(1,101))-set(paths))}')

for qid, f in sorted(paths.items()):
    txt=f.read_text(encoding='utf-8')
    # remove previous V2 block if rerun, preserving following "参考资料" if any.
    if MARK in txt:
        txt=txt.split(MARK)[0].rstrip()+"\n"
    # Insert before reference section/source note when possible so references remain last.
    sec=block_section(qid,P[qid]).rstrip()+"\n"
    insert_at = txt.find('\n## 参考资料')
    if insert_at >= 0:
        txt = txt[:insert_at].rstrip()+"\n"+sec+txt[insert_at:]
    else:
        txt = txt.rstrip()+"\n"+sec
    f.write_text(txt,encoding='utf-8')

print('enriched',len(paths),'question markdown files')
